 import unittest
from candidate import add

class TestAdd(unittest.TestCase):
    def test_add_positive_numbers(self):
        self.assertEqual(add(2, 3), 5)
        self.assertEqual(add(5, 7), 12)

    def test_add_negative_numbers(self):
        self.assertEqual(add(-2, -3), -5)
        self.assertEqual(add(-5, -7), -12)

    def test_add_mixed_numbers(self):
        self.assertEqual(add(-2, 3), 1)
        self.assertEqual(add(-5, 7), 2)

    def test_add_zero(self):
        self.assertEqual(add(0, 5), 5)
        self.assertEqual(add(5, 0), 5)

    def test_add_with_floats(self):
        self.assertAlmostEqual(add(2.5, 3.5), 6.0)
        self.assertAlmostEqual(add(-2.5, 3.5), 1.0)

    def test_add_empty_inputs(self):
        self.assertEqual(add(None, None), None)
        self.assertEqual(add(0, None), None)
        self.assertEqual(add(None, 0), None)

    def test_add_type_errors(self):
        self.assertRaises(TypeError, add, 2, 'string')
        self.assertRaises(TypeError, add, 'string', 2)

if __name__ == '__main__':
    unittest.main()
